-- Frotas Rastreadores v2: novos campos + status expandido + importação planilha

ALTER TABLE public.frotas_rastreadores
  ADD COLUMN IF NOT EXISTS contrato integer,
  ADD COLUMN IF NOT EXISTS contrato_assinado boolean,
  ADD COLUMN IF NOT EXISTS agendamentos_frustrados integer DEFAULT 0,
  ADD COLUMN IF NOT EXISTS termo_assinado text;
ALTER TABLE public.frotas_rastreadores DROP CONSTRAINT IF EXISTS frotas_rastreadores_status_check;
ALTER TABLE public.frotas_rastreadores
  ADD CONSTRAINT frotas_rastreadores_status_check
  CHECK (status IN ('sem_rastreador','em_andamento','concluido','aguardando_motorista','agendado'));
CREATE INDEX IF NOT EXISTS idx_frotas_rastreadores_contrato ON public.frotas_rastreadores (contrato);
